  name                                TEXT                ,                     -- Display name of the job board (e.g., ZipRecruiter, Indeed, LinkedIn, WeWorkRemotely).
  description                         TEXT                ,                     -- Notes about this board's behavior, rate limits, or special handling requirements.
  is_enabled                          BOOLEAN             ,                     -- Whether this board is active for search runs.
  max_pages                           INTEGER             ,                     -- Maximum number of result pages to crawl per search URL. Default is 3.
  is_headless                         BOOLEAN             ,                     -- Whether to run the Playwright browser in headless mode for this board.
  browser_channel                     TEXT                                      -- Optional browser variant to use (e.g., msedge). NULL means default Chromium.
);
