-- ScoreResults: Table: ScoreResults - Component and final scores for a job listing within a specific search run.
-- ----------------------------------------------------------------------------
CREATE TABLE score_results (
  score_result_id                     TEXT                 PRIMARY KEY,         -- Primary key for score results.
  job_listing                         TEXT                ,                     -- The job listing that was scored.
  search_run                          TEXT                ,                     -- The search run during which this score was produced.
  fit_score                           NUMERIC             ,                     -- Semantic similarity to resume (0.0 - 1.0). Based on cosine distance in resume ChromaDB collection.
  archetype_score                     NUMERIC             ,                     -- Match to role archetypes (0.0 - 1.0). Based on cosine distance in role_archetypes collection.
  history_score                       NUMERIC             ,                     -- Match to past accepted decisions (0.0 - 1.0). Only 'yes' verdicts contribute.
  comp_score                          NUMERIC             ,                     -- Compensation alignment with base salary (0.0 - 1.0). Non-linear curve; 0.5 when comp is missing.
  negative_score                      NUMERIC             ,                     -- Penalty score from negative signal matches (0.0 - 1.0). Subtracted from positive scores.
  culture_score                       NUMERIC             ,                     -- Match to positive culture/quality dimensions (0.0 - 1.0).
  is_disqualified                     BOOLEAN             ,                     -- Whether the LLM disqualifier flagged this listing. If true, final score is forced to 0.0.
  disqualifier_reason                 TEXT                ,                     -- Free-text explanation from the LLM disqualifier about why the role was flagged.
  duplicate_boards                    TEXT                                      -- Comma-separated list of other boards where this same job appeared (cross-board deduplication).
);
COMMENT ON TABLE score_results IS 'Table: ScoreResults - Component and final scores for a job listing within a specific search run.';
