-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_score_results_name(p_score_result_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(calc_score_results_job_listing_name(p_score_result_id), ' - ', calc_score_results_search_run_name(p_score_result_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_score_results_final_score
-- Field: ScoreResults.FinalScore
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_score_results_final_score(p_score_result_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_disqualified FROM score_results WHERE score_result_id = p_score_result_id), FALSE) THEN (0)::text ELSE (GREATEST(0, (COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT fit_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT archetype_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT history_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT comp_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT culture_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT negative_score FROM score_results WHERE score_result_id = p_score_result_id)) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0))))::text END)::numeric;
$$ LANGUAGE sql STABLE;

